using System.Numerics;
using DynamicFrontline.Core.VerifiedCombat;
using DynamicFrontline.Core.ExperimentalCombat;
using DynamicFrontline.Integration;
static partial class Tests
{
    static partial void Navigation()
    {
        Test("Astar weighted priority example and single addition",()=>{Eq(NavigationMath.AstarPriority(3,4,10).Priority,16.553300858899107,1e-14);Eq(NavigationMath.AstarPriority(-3,-4,10).Priority,NavigationMath.AstarPriority(3,4,10).Priority,0);Check(NavigationMath.AstarPriority(16777216,1,0).SingleSum==16777216);Reject(()=>NavigationMath.AstarPriority(float.NaN,1,0));});
        Test("Navigation consumer valid not adapter proof",()=>{Check(NavigationMath.SubGraphConsumerAccepts(1)&&NavigationMath.SubGraphConsumerAccepts(2));Check(!NavigationMath.SubGraphConsumerAccepts(3));Check(NativeNavigationStatusPolicy.Path(2)==RouteState.Unknown);Check(NativeNavigationStatusPolicy.Path(3,true,true)==RouteState.Unknown);Check(NativeNavigationStatusPolicy.Path(4)==RouteState.Unknown);Check(NativeNavigationStatusPolicy.Path(4,false,true)==RouteState.Blocked);});
        Test("CyclicRandom upper endpoint wrap counts no-draw",()=>{var q=new float[100];q[0]=1;q[1]=.25f;var r=new CyclicRandom(q,99);Eq(r.NextFloat(0,1000),1000);Eq(r.NextFloat(2,6),3);Check(r.Index==1&&r.ValuesConsumed==2);Eq(r.NextFloat(7,7),7);Reject(()=>r.NextFloat(4,3));Reject(()=>r.NextFloat(float.NaN,1));Check(r.Index==1&&r.ValuesConsumed==2);});
        Test("CyclicRandom different initial indices",()=>{var q=Enumerable.Range(0,100).Select(i=>i/100f).ToArray();Eq(new CyclicRandom(q,6).NextFloat(0,1),.07);Eq(new CyclicRandom(q,7).NextFloat(0,1),.08);});
        Test("Entity version reuse rejects old handle",()=>{var id=new VersionAwareIdentity(Guid.NewGuid(),1,7,1);var old=new LifecycleObservation(id,1,10,false,false,false,false,false,true);Check(IdentityValidation.Validate(old,old)==IdentityDecision.Accepted);var disposed=old with{Disposed=true};Check(IdentityValidation.Validate(old,disposed)==IdentityDecision.Disposed);var reused=old with{Identity=id with{EntityVersion=2},Revision=3};Check(IdentityValidation.Validate(old,reused)==IdentityDecision.StaleVersion);Check(IdentityValidation.Validate(reused,reused)==IdentityDecision.Accepted);});
        Test("Entity stale snapshot world session and owner",()=>{var a=new LifecycleObservation(new(Guid.NewGuid(),1,7,2),5,10,false,false,false,false,false,true);Check(IdentityValidation.Validate(a,a with{Revision=6})==IdentityDecision.StaleSnapshot);Check(IdentityValidation.Validate(a,a with{OwnerId=20})==IdentityDecision.Accepted);Check(IdentityValidation.Validate(a,a with{Identity=a.Identity with{SessionId=Guid.NewGuid()}})==IdentityDecision.DifferentSession);Check(IdentityValidation.Validate(a,a with{Identity=a.Identity with{WorldId=2}})==IdentityDecision.DifferentWorld);});
        Test("Lifecycle death remove fog and spatial distinct from disposal",()=>{var a=new LifecycleObservation(new(Guid.NewGuid(),1,7,2),5,10,false,false,false,false,false,true);foreach(var b in new[]{a with{Death=true},a with{Dead=true},a with{RemoveUnit=true},a with{FogRemove=true},a with{SpatialPresent=false}})Check(IdentityValidation.Validate(b,b)==IdentityDecision.Accepted);Check(IdentityValidation.Validate(a with{Disposed=true},a)==IdentityDecision.Disposed);});
        Test("LastKnown diagnostic squared XZ boundaries no contact",()=>{var p=LastKnownNavigationFragment.Evaluate(true,false,Vector3.Zero,new(800,9999,0),new(800,0,0),Vector3.Zero,1);Check(p.WouldWriteActual);Check(!LastKnownNavigationFragment.Evaluate(true,false,Vector3.Zero,new(800.001f,0,0),new(800.001f,0,0),Vector3.Zero,1).WouldWriteActual);Check(!LastKnownNavigationFragment.Evaluate(true,false,Vector3.Zero,Vector3.Zero,new(25,0,0),Vector3.Zero,1).CompletionDistanceReached);});
        Test("H1 finite experimental boundaries and invalid domain",()=>{Eq(H1FiniteResearch.Evaluate(0).Result,0);Eq(H1FiniteResearch.Evaluate(1).Result,Math.PI/4);foreach(float x in new[]{.4375f,.6875f,1.1875f,2.4375f,100f})Eq(H1FiniteResearch.Evaluate(x).Result,-H1FiniteResearch.Evaluate(-x).Result,0);Check(H1FiniteResearch.Evaluate(float.MaxValue).LargeInputHandler);Reject(()=>H1FiniteResearch.Evaluate(float.NaN));});
    }
}
